WITH fixes(slug,pos,q,a,why) AS (VALUES ('pcac-2026-direito-administrativo-06-agentes-publicos',5,'Dois cargos acumuláveis pela Constituição podem ser exercidos com horários incompatíveis desde que ambos sejam públicos.',false,'Errado. Mesmo nas exceções de acumulação admitidas pela Constituição, o art. 37, XVI exige compatibilidade de horários. A permissão constitucional não dispensa verificar a jornada concreta.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',11,'No balanço patrimonial, disponibilidades como caixa tendem a aparecer antes de estoques pela ordem de liquidez.',true,'Certo. Caixa já representa dinheiro disponível, enquanto estoques precisam ser vendidos. A apresentação do ativo considera, em regra, a ordem decrescente de liquidez.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',12,'Na apresentação do ativo, estoques normalmente aparecem depois de caixa porque são menos líquidos.',true,'Certo. Estoques dependem de venda para conversão em caixa; o dinheiro em caixa já é disponível. Essa distinção ilustra a ordem decrescente de liquidez.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',13,'Uma máquina adquirida exclusivamente para revenda por uma loja de máquinas deve ser registrada como imobilizado.',false,'Errado. A finalidade de revenda no curso normal dos negócios indica estoque. O imobilizado corresponde, em regra, a bens corpóreos mantidos para uso na produção, prestação de serviços ou administração.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',14,'O ativo fiscal diferido é a mesma coisa que o antigo grupo societário denominado ativo diferido.',false,'Errado. O antigo grupo ativo diferido deixou de integrar a estrutura normal do balanço. Ativo fiscal diferido é conceito distinto, associado a tributos sobre o lucro e diferenças temporárias, conforme normas específicas.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',15,'Para classificar uma máquina como mantida para venda, a entidade precisa atender aos critérios do CPC 31, não apenas anunciar a intenção de vendê-la.',true,'Certo. Entre os requisitos estão disponibilidade imediata para venda nas condições atuais e alta probabilidade de concretização. A intenção isolada não satisfaz o CPC 31.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',16,'Uma máquina disponível para venda imediata e cuja alienação é altamente provável pode atender aos requisitos de ativo mantido para venda.',true,'Certo. O CPC 31 exige avaliação dos requisitos normativos, inclusive disponibilidade imediata e alta probabilidade da venda. A classificação não é automática: verifique também as demais condições aplicáveis.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',17,'Uma obrigação vencida e exigível imediatamente deve ser tratada como não circulante apenas porque o contrato original previa prazo de cinco anos.',false,'Errado. A classificação do passivo depende dos direitos existentes na data do balanço e da exigibilidade. O prazo original não prevalece automaticamente se a obrigação já é exigível à vista.'),
('pcac-2026-contabilidade-04-demonstracoes-balanco-dre-regimes',18,'O aumento do preço de mercado de um prédio autoriza automaticamente reconhecer uma nova reserva de reavaliação no patrimônio líquido.',false,'Errado. A antiga reserva de reavaliação não pode ser criada livremente. Mensuração e reconhecimento exigem base normativa específica; valorização de mercado isolada não autoriza esse lançamento.'),
('pcac-2026-acre-chico-mendes-reservas-seguranca-fronteira',4,'A posição fronteiriça do Acre exige distinguir fronteiras internacionais de divisas com outros estados brasileiros.',true,'Certo. O Acre faz fronteira com países vizinhos e também possui divisas internas com unidades federativas brasileiras. Em prova, não trate divisa estadual como fronteira internacional.'),
('pcac-2026-realidade-acre-historia-geografia-economia',4,'Amazonas e Rondônia são países que fazem fronteira internacional com o Acre.',false,'Errado. Amazonas e Rondônia são estados brasileiros. O Acre possui fronteiras internacionais com Peru e Bolívia, mas seus limites com Amazonas e Rondônia são divisas estaduais.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL THEN jsonb_set(jsonb_set(jsonb_set(e.value,'{q}',to_jsonb(f.q)),'{a}',to_jsonb(f.a)),'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;